function getRouterText(item) {
  return (
    item.json.content ||
    item.json.message?.content ||
    item.json.data?.message?.content ||
    ''
  ).trim();
}

const item0 = items[0] || { json: {} };
const raw = getRouterText(item0);

let obj = {};
try {
  obj = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) {
    try { obj = JSON.parse(m[0]); } catch (e2) { obj = {}; }
  }
}

// Webhook'tan orijinal soruyu al
let wbMsg = '';
try {
  const wb = $items('Webhook')[0].json;
  wbMsg = wb.body?.message || wb.body?.question || wb.body?.soru || wb.message || wb.question || wb.soru || '';
} catch (e) {}

const question = (obj.question || wbMsg || '').trim();

let collection = String(obj.collection || 'ship_manuals_v3').trim().replace(/^=+/, '');
const allowed = new Set(['ship_electric','ship_ccr','ship_manuals','ship_manuals_v2','ship_manuals_v3']);
if (!allowed.has(collection)) collection = 'ship_manuals_v3';

let folder = obj.folder ?? null;
if (typeof folder === 'string') {
  folder = folder.trim();
  if (!folder) folder = null;
}

let query_en = String(obj.query_en || '').trim();
if (!query_en) query_en = question;

return [{ json: { question, query_en, collection, folder } }];

// Context oluştur ve Claude için sistem promptu hazırla
const route = $node['APPLY_ROUTE'].json;
const question = route.question || '';

// Qdrant'tan gelen item'ları normalize et
const cleaned = items
  .map((it) => it.json.document ? it.json.document : it.json)
  .map((d) => {
    const text = String(d.pageContent || d.page_content || '').trim();
    const md = d.metadata || {};
    return {
      text,
      source: md.sourceName || md.fileName || md.source || 'Bilinmiyor',
      page: md.page ?? '?',
      chunk: md.chunk ?? '',
      folder: md.folder || ''
    };
  })
  .filter(h => h.text.length > 80)
  .filter(h => !/^[\W_]+$/.test(h.text));

const top = cleaned.slice(0, 12); // Top 12 chunk yeterli, daha fazlası prompt'u şişirir

// Her chunk için kaynak bilgisini ekleyerek context oluştur
const context = top.map((h, i) => {
  return `[${i+1}] Kaynak: ${h.source} | Sayfa: ${h.page}\n${h.text}`;
}).join('\n\n---\n\n');

// Kaynak listesi
const sourcesList = top.map((h, i) => `  ${i+1}. ${h.source} — Sayfa ${h.page}`).join('\n');

const systemPrompt = `Sen deneyimli bir gemi teknik uzmanısın. Sana verilen gemi manueli alıntılarına dayanarak teknik soruları cevaplıyorsun.

KEYİF KURALLARI:
1. SADECE aşağıdaki CONTEXT içindeki bilgileri kullan — asla uydurma yapma
2. Teknik detayları eksiksiz ver, kesmeden anlat
3. Adım adım prosedür gerekiyorsa numaralı liste kullan
4. Cevabının SONUNDA her zaman "📚 KAYNAKLAR:" bölümü ekle
5. Kaynak formatı: • Kaynak: [dosya adı] Sayfa: [sayfa no]
6. Bilgi yetersizse dürüstçe "Bu konuda yeterli bilgi bulunamadı" de ve hangi kaynaklara bakıldığını belirt

MEVCUT BELGE ALINTILARI:
${context}

KAYNAK ÖZETİ (cevap sonunda kullan):
${sourcesList}`;

return [{
  json: {
    systemPrompt,
    userText: question,
    question,
    sourcesList
  }
}];

