const claudeResp = $input.first().json;
// Claude API response formatı: content[0].text
const answer = claudeResp.content?.[0]?.text || claudeResp.content || 'Cevap üretilemedi.';
const question = $items('BUILD_PROMPT')[0].json.question || '';
const sourcesList = $items('BUILD_PROMPT')[0].json.sourcesList || '';

return [{
  json: {
    text: answer,
    sources: sourcesList,
    question,
    ok: true
  }
}];
